      <img src="https://www.kiantiong.com/images/kautian29-2.jpg" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian29-3.jpg" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian29-4.jpg" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian29-5.jpg" class="carousel-img" loading="lazy" />
      <img src="https://www.kiantiong.com/images/kautian29-6.jpg" class="carousel-img" loading="lazy" />
    </div>
  </div>
  <div class="carousel-controls">
    <button class="carousel-btn prev">&#8592;</button>
    <div class="carousel-indicator">
      <span class="carousel-current">1</span>/<span class="carousel-total"
        >5</span
      >
    </div>
    <button class="carousel-btn next">&#8594;</button>
  </div>
</div>
<script>
  (function () {
    const container = document.currentScript.previousElementSibling;
    const track = container.querySelector(".carousel-track");
    const images = track.querySelectorAll("img");
    const prevBtn = container.querySelector(".carousel-btn.prev");
    const nextBtn = container.querySelector(".carousel-btn.next");
    const indicator = container.querySelector(".carousel-indicator");
    const current = indicator.querySelector(".carousel-current");
    let idx = 0;
    function update() {
      track.style.transform = `translateX(-${idx * 100}%)`;
      current.textContent = idx + 1;
    }
    prevBtn.onclick = function () {
      idx = (idx - 1 + images.length) % images.length;
      update();
    };
    nextBtn.onclick = function () {
      idx = (idx + 1) % images.length;
      update();
    };

    let startX = null;
    track.addEventListener("touchstart", (e) => {
      startX = e.touches[0].clientX;
    });
    track.addEventListener("touchend", (e) => {
      if (startX === null) return;
      let dx = e.changedTouches[0].clientX - startX;
      if (Math.abs(dx) > 50) {
        if (dx < 0) nextBtn.onclick();
        else prevBtn.onclick();
      }
      startX = null;
    });
  })();
</script>

<h2 id="咒語貧惰包">咒語貧惰包</h2>
<p>揣所有 4 字詞（數字會當換做其他的）：<br>
<code>[^a-z]{4}</code></p>
<p>AA 仔 B：<br>
<code>^(.)\1仔.$</code></p>
<p>有無四字詞：<br>
<code>^[有無].[有無].$</code></p>
<p>色水 ABB 形容詞：<br>
<code>^[紅黃青綠藍紫烏白](.)\1$</code></p>
<p>數字四字詞：<br>
<code>^[一二三四五六七八九].[一二三四五六七八九].$</code></p>
<p>A 跤 B 手：<br>
<code>^.跤.手$</code></p>
<p>會/袂環綴三字詞：<br>
<code>^[會袂].[得通過]$</code></p>
<p>AA 疊詞：<br>
<code>^(.)\1$</code></p>
<p>AAB 疊詞：<br>
<code>^([^a-z])\1.$</code></p>
<p>ABB 疊詞：<br>
<code>^.(.)\1$</code></p>
<p>ABA 疊詞：<br>
<code>^(.).\1$</code></p>
<p>AABB 疊詞：<br>
<code>^(.)\1(.)\2$</code></p>
<p>ABBA 疊詞：<br>
<code>^(.)(.)\2\1$</code></p>
<p>ABCA 疊詞：<br>
<code>^(.)..\1$</code></p>
<p>ABAB 疊詞：<br>
<code>^(.)(.)\1\2$</code></p>
<p>ABAC 疊詞：<br>
<code>^([^a-z]).\1.$</code></p>
<p>ABCB 疊詞：<br>
<code>^.(.).\1$</code></p>
